  'plans.faqWhatIsPlusAnswer': 'Սա Chatyy-ի պրեմիում պլանն է, որը պաշտպանում է ձեր բոլոր խոսակցությունները, լուսանկարները և տեսանյութերը: Chatyy One-ի հետ, նույնիսկ եթե դուք անզգուշաբար ջնջեք ինչ-որ բան, կարող եք վերականգնել մինչև 30 օր: Բացի այդ, դուք ստանում եք 200GB պահեստ, One AI որպես անձնական օգնական, և կարող եք ուղարկել մինչև 100MB ֆայլեր.',
  'plans.faqCancelAnswer': 'Ձեր պլանը շարունակում է ակտիվ լինել վճարված ժամկետի ավարտին: Այդ ժամանակ, դուք վերադառնում եք անվճար պլանին: Ձեր լուսանկարներն ու տեսանյութերը, որոնք գերազանցում են 15GB, կպահվեն ևս 30 օր, որպեսզի դուք կարողանաք ներբեռնել.',
  'plans.faqHowFamily': 'Ինչպե՞ս է աշխատում Pro պլանը:',
  'plans.faqHowFamilyAnswer': 'Դուք կարող եք ավելացնել մինչև 4 մարդու ձեր ընտանիքից: Բոլորը կիսում են 500GB պահեստ և ստանում են Chatyy One-ի բոլոր առավելությունները: Յուրաքանչյուր անձ ունի իր մասնավոր տարածքը՝ ոչ ոք չի տեսնում մյուսների ֆայլերը.',
  'plans.faqChangePlanAnswer': 'Այո! Եթե դուք վերակառուցեք Plus-ից Pro, միայն տարբերությունը կվճարվի: Եթե դուք նվազեցնեք, ներկայիս պլանը շարունակվում է մինչև ժամկետի ավարտը.',
